INSERT INTO `apicompany` (`name`, `description`, `long_description`, `folder`, `dateupdated`, `staffid`, `languageid`) VALUES
('Construímos soluções sólidas e econômicas', 'A MetaBix Biotech é uma empresa global inovadora na previsão de doenças que afetam plantas, animais e humanos.', 'A MetaBix Biotech é uma empresa global inovadora na previsão de doenças que afetam plantas, animais e humanos. A prevenção de doenças se baseia no diagnóstico populacional precoce, antecipando surtos em pelo menos duas semanas com IA e biotecnologia, garantindo ecossistemas e comunidades saudáveis.', 'company', '2025-09-24 13:46:41', 1, 1),
('We build solid and economical solutions', 'MetaBix Biotech is a Global Game Changer in the prediction of diseases affecting plants, animals and humans', 'MetaBix Biotech is a Global Game Changer in the prediction of diseases affecting plants, animals and humans. Disease prevention based on early populational diagnostic, anticipating outbreaks by at least two weeks with AI and biotechnology, ensuring healthy ecosystems and communities.', 'company', '2025-09-24 13:46:41', 1, 2),
('Construimos soluciones sólidas y económicas.', 'MetaBix Biotech es una empresa pionera global en la predicción de enfermedades que afectan a plantas, animales y humanos.', 'MetaBix Biotech es una empresa pionera global en la predicción de enfermedades que afectan a plantas, animales y humanos. La prevención de enfermedades se basa en el diagnóstico poblacional temprano, anticipando brotes con al menos dos semanas de anticipación mediante IA y biotecnología, garantizando ecosistemas y comunidades saludables.', 'company', '2025-09-24 13:46:54', 1, 3);
