INSERT INTO `apicompany_items_translation` (`id`, `name`, `description`, `itemid`, `languageid`) VALUES
(1, 'Nossa Missão', 'A missão da metaBIX Biotech é reduzir o impacto de doenças e contaminação microbiológica por meio do diagnóstico e da análise de dados precisos e da previsão inteligente de doenças causadas por vírus e bactérias a partir de amostras ambientais.', 1, 1),
(2, 'Our Mission', 'The mission of metaBIX Biotech is to reduce the impact of diseases and microbiological contamination through the diagnosis and analysis of accurate data and through the intelligent prediction of diseases caused by viruses and bacteria from environmental samples.', 1, 2),
(3, 'Nuestra Misión', 'La misión de metaBIX Biotech es reducir el impacto de las enfermedades y la contaminación microbiológica mediante el diagnóstico y análisis de datos precisos, así como la predicción inteligente de enfermedades causadas por virus y bacterias a partir de muestras ambientales.', 1, 3),
(4, 'Nossa Visão', 'Um mundo sem ameaças microbiológicas, impulsionado por tecnologia avançada, prevenção proativa e uma sociedade saudável e equitativa.', 2, 1),
(5, 'Our Vision', 'A world without microbiological threats, driven by advanced technology, proactive prevention and a healthy and equitable society.', 2, 2),
(6, 'Valores', 'Un mundo sin amenazas microbiológicas, impulsado por tecnología avanzada, prevención proactiva y una sociedad saludable y equitativa.', 2, 3),
(7, 'Nossa Visão', 'Um mundo sem ameaças microbiológicas, impulsionado por tecnologia avançada, prevenção proativa e uma sociedade saudável e equitativa.', 2, 1),
(8, 'Values', 'Speed, accuracy, customer centric, innovation, trust, commitment and ease of use.', 2, 2),
(9, 'Valores', 'Rapidez, precisão, foco no cliente, inovação, confiança, comprometimento e facilidade de uso.', 2, 3);
