INSERT INTO `apiprojects_translation` (`id`, `name`, `description`, `long_description`, `projectid`, `languageid`) VALUES
(1, 'Edifício Nobile', 'O extenso projecto de um edifício de escritórios com uma área de 2.872,32 metros quadrados para a agro-holding é mais um caso da equipe ST - Estrutural.', '<p>O extenso projecto de um edif&#237;cio de escrit&#243;rios com uma &#225;rea de 2.872,32 metros quadrados para a agro-holding &#233; mais um caso da equipe ST - Estrutural.</p>', 1, 1),
(2, 'Edifício Nobile', 'The extensive project of a commercial building with an area of ​​2,872.32 square meters for the agro-holding is another case of the ST - Estrutural team.', '<p>The extensive project of a commercial building with an area of &#8203;&#8203;2,872.32 square meters for the agro-holding is another case of the ST - Estrutural team.</p>', 1, 2),
(3, 'Edifício Nobile', 'El amplio proyecto de un edificio comercial con una superficie de 2.872,32 metros cuadrados para el holding agropecuario es otro caso del equipo de ST – Estrutural.', '<p>El amplio proyecto de un edificio comercial con una superficie de 2.872,32 metros cuadrados para el holding agropecuario es otro caso del equipo de ST &#8211; Estrutural.</p>', 1, 3);
