INSERT INTO `apislides_translation` (`id`, `name`, `description`, `slideid`, `languageid`) VALUES
(1, 'Dispositivo MetaBix Biotech para amostragem de ar', 'Nossa plataforma fornece alertas antecipados aos nossos clientes por meio de software especializado, permitindo que eles tomem medidas preventivas eficazes.', 1, 1),
(2, 'MetaBix Biotech air sampling device', 'Our platform provides early warnings to our clients through specialized software, allowing them to take effective preventive measures.', 1, 2),
(3, 'Dispositivo MetaBix Biotech para muestreo de aire', 'Nuestra plataforma proporciona alertas tempranas a nuestros clientes a través de un software especializado, permitiéndoles tomar medidas preventivas efectivas.', 1, 3),
(4, 'Pressão ambiental de infecção', '(no ar), incluindo doenças conhecidas e emergentes.', 2, 1),
(5, 'Environmental Pressure of Infection', '(in the air), including both known and emerging diseases.', 2, 2),
(6, 'Presión ambiental de la infección', '(en el aire), incluidas tanto las enfermedades conocidas como las emergentes.', 2, 3);
