INSERT INTO `apitechnology` (`name`, `description`, `long_description`, `folder`, `dateupdated`, `staffid`, `languageid`) VALUES
('Construímos soluções sólidas e econômicas', 'Desenvolvemos uma solução tecnológica avançada que combina hardware, biotecnologia e inteligência artificial para avaliar a Pressão Ambiental de Infecção (no ar), incluindo doenças conhecidas e emergentes.', 'Desenvolvemos uma solução tecnológica avançada que combina hardware, biotecnologia e inteligência artificial para avaliar a Pressão Ambiental de Infecção (no ar), incluindo doenças conhecidas e emergentes. Nossa plataforma fornece alertas antecipados aos nossos clientes por meio de software especializado, permitindo que tomem medidas preventivas eficazes. Graças à nossa tecnologia inovadora, conseguimos alertar nossos usuários e clientes com pelo menos duas semanas de antecedência antes do início do surto, melhorando significativamente a segurança e o bem-estar.', 'company', '2025-09-24 13:58:39', 1, 1),
('We build solid and economical solutions', 'We have developed an advanced technological solution that combines hardware, biotechnology, and artificial intelligence to assess the Environmental Pressure of Infection (in the air), including both known and emerging disease', 'We have developed an advanced technological solution that combines hardware, biotechnology, and artificial intelligence to assess the Environmental Pressure of Infection (in the air), including both known and emerging diseases. Our platform provides early warnings to our clients through specialized software, allowing them to take effective preventive measures. Thanks to our innovative technology, we are able to alert our users and clients at least two weeks in advance before the outbreak begins, significantly improving safety and well-being.', 'technology', '2025-09-24 13:58:01', 1, 2),
('Construimos soluciones sólidas y económicas.', 'Hemos desarrollado una solución tecnológica avanzada que combina hardware, biotecnología e inteligencia artificial para evaluar la presión ambiental de infección (en el aire), incluyendo enfermedades conocidas y emergentes.', 'Hemos desarrollado una solución tecnológica avanzada que combina hardware, biotecnología e inteligencia artificial para evaluar la presión ambiental de infección (en el aire), incluyendo enfermedades conocidas y emergentes. Nuestra plataforma proporciona alertas tempranas a nuestros clientes mediante software especializado, lo que les permite tomar medidas preventivas eficaces. Gracias a nuestra tecnología innovadora, podemos alertar a nuestros usuarios y clientes con al menos dos semanas de antelación al inicio del brote, mejorando significativamente la seguridad y el bienestar.', 'company', '2025-09-24 13:58:39', 1, 3);
