(1, 'Precisão', 'Focus on environmental pressure of infection (known and emerging diseases)', 1, 1),
(2, 'Precision', 'Focus on environmental pressure of infection (known and emerging diseases)', 1, 2),
(3, 'Precision', '<p>Se você procura por uma oportunidade de crescimento, aumento de clientes e desenvolvimento profissional em seu ramo na cidade e região, esta é a oportunidade perfeita para você.</p>', 1, 3),
(4, 'Escabilidade', 'Aplicável a aves, suínos, plantações e indústria alimentícia', 2, 1),
(5, 'Scalability', 'Applicable to poultry, swine, crops and the food industry', 2, 2),
(6, 'Escalabilidad', 'Aplicable a aves de corral, cerdos, cultivos e industria alimentaria.', 2, 3),
(7, 'Impacto transversal', 'Protege empresas, reduz custos e previne crises de saúde pública', 3, 1),
(8, 'Cross-cutting impact', 'Protects businesses, reduces costs, and prevents public health crises', 3, 2),
(9, 'Impacto transversal', 'Protege a las empresas, reduce costos y previene crisis de salud pública.', 3, 3);
